  var dirs = [[0, 1], [1, 0], [1, 1], [1, -1]];
  for (var y = 0; y < N; y++) for (var c = 0; c < N; c++) {
    if (x[y][c] == '.') continue;
    for (var d = 0; d < dirs.length; d++) {
      var k = 1;
      while (k < K) {
        var yy = y + dirs[d][0] * k, cc = c + dirs[d][1] * k;
        if (yy < 0 || yy >= N || cc < 0 || cc >= N || x[yy][cc] != x[y][c]) break;
        k++;
      }
      if (k == K) return x[y][c];
    }
  }
  return null;
}

